import{_ as n,l as r,o as e,c as s,v as o,p,x as i,d as l,i as h,S as c}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"Hopkins 部分相干成像","description":"","frontmatter":{"title":"Hopkins 部分相干成像","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/hopkins-1953-paper.md","filePath":"litho/hopkins-1953-paper.md","lastUpdated":1789023840000}'),d={name:"litho/hopkins-1953-paper.md"};function C(A,a,E,k,m,_){const t=r("Mermaid");return e(),s("div",null,[a[1]||(a[1]=o('<h1 id="hopkins-部分相干成像" tabindex="-1">Hopkins 部分相干成像 <a class="header-anchor" href="#hopkins-部分相干成像" aria-label="Permalink to &quot;Hopkins 部分相干成像&quot;">​</a></h1><div class="epigraph"><p>部分相干成像不是「有一点相干」的口语，而是把空中像强度写成物体频谱的双线性型；交叉系数只含照明与两个投影瞳。</p><footer>—— H. H. Hopkins, On the diffraction theory of optical images, Proc. R. Soc. Lond. A 217, 408 (1953)</footer></div><p>附录对照，不插入主干。<a href="/litho/computational-litho-paper">上一课</a>把计算光刻收成对 Hopkins 前向的可制造逆。本篇对照 1953 年原文：互强度与传递交叉系数从哪来，主干里的 <a href="/litho/hopkins-tcc">Hopkins TCC</a> 课默认已经会用。不重做全芯片 OPC，也不把这篇论文写成 DTCO 的替代教材。Levinson 的书对照从下一篇开始。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>主干的<a href="/litho/partial-coherence">部分相干</a>已经用 \\(\\sigma\\) 和 TCC 把产线照明说清。缺口是文献：Hopkins 面对的是显微镜与一般光学仪器的部分相干，不是 KrF 胶。1953 年要把 Abbe 的相干叠加与非相干强度叠加收成同一套互强度传播，使任意光源形状、任意光瞳的像强度有可积的核。</p><p>没有这篇，TCC 会像软件开关。有这篇，才看清：掩模（物体透过率）只进一对空间频率，照明与镜头进交叉系数，两者可分离。计算光刻专文里的「固定光源则预计算 TCC」就是这条分离。</p><h3 id="不是产线第一课" tabindex="-1">不是产线第一课 <a class="header-anchor" href="#不是产线第一课" aria-label="Permalink to &quot;不是产线第一课&quot;">​</a></h3><p>附录不从惠更斯原理重讲。主干波动光学已经把衍射与 NA 钉过。本篇只对照：Hopkins 的互强度 \\(J\\) 如何让强度在像面成为双线性，以及为何低 \\(k_1\\) 的 OPC 仍活在这个 1953 年的核上——直到厚掩模逼出严格电磁。</p><p><span class="marginnote">论文写的是光学像强度，没有抗蚀剂。胶核是后来产线加上的紧凑段，不要读成 Hopkins 已经含显影。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Hopkins 用互强度描述部分相干场：两点的互相关沿系统传播，像面强度是互强度的对角。对投影系统，物体频谱的每一对频率 \\((f_1,g_1)\\)、\\((f_2,g_2)\\) 乘传递交叉系数 \\(\\mathrm{TCC}(f_1,g_1;f_2,g_2)\\)，TCC 是照明光瞳与两个错位投影光瞳的重叠积分。照明形状全部进 TCC；换偶极等于换核，不必重解麦克斯韦。</p><p>主干 <a href="/litho/hopkins-tcc">hopkins-tcc</a> 把这收成 OPC 可调用的本征展开（和差相干分解）。读 1953 年时对照的是<strong>分离定理</strong>本身，不是 SOCS 的实现细节。Wong 的投影成像教材是这条文献进入光刻教室的桥梁，仍属对照，不插入成像课序的递进。</p>',12)),(e(),p(c,null,{default:i(()=>[h(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20J%5B%22%E4%BA%92%E5%BC%BA%E5%BA%A6%E4%BC%A0%E6%92%AD%22%5D%20--%3E%20TCC%5B%22TCC%3A%20%E7%85%A7%E6%98%8E%20%E2%88%A9%20%E4%B8%A4%E9%94%99%E4%BD%8D%E7%9E%B3%22%5D%0A%20%20M%5B%22%E7%89%A9%E4%BD%93%E9%A2%91%E8%B0%B1%22%5D%20--%3E%20BL%5B%22%E5%8F%8C%E7%BA%BF%E6%80%A7%E5%BC%BA%E5%BA%A6%22%5D%0A%20%20TCC%20--%3E%20BL%0A%20%20BL%20--%3E%20AI%5B%22%E7%A9%BA%E4%B8%AD%E5%83%8F%20I(x%2Cy)%22%5D%0A%20%20AI%20--%3E%20RES%5B%22%E8%83%B6%E6%A0%B8%3A%20%E4%B8%BB%E5%B9%B2%E5%8F%A6%E5%8A%A0%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h3 id="与-abbe-的对照" tabindex="-1">与 Abbe 的对照 <a class="header-anchor" href="#与-abbe-的对照" aria-label="Permalink to &quot;与 Abbe 的对照&quot;">​</a></h3><p>Abbe 观点：每个源点相干成像，再对源非相干积分。Hopkins 观点：先形成互强度核，再对物体积分。数值上等价，计算上 TCC 可预计算。计算光刻选 Hopkins 形式，因为全芯片掩模变、光源暂时固定。这不是 1953 年论文的产线动机，是后人读法。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>部分相干的物理是：扩展源的不同点互不相干，同一源点发出的衍射级在像面相干干涉。双线性型把「对哪一对级相干」编码进 TCC 的支撑：两频率之差进得了照明填充的区域，才有交叉项。\\(\\sigma\\) 越大，TCC 越宽，密图形调制往往掉得快——主干对比度课用过这句，原文给的是核，不是 NILS。产线把照明半径写成相对投影 \\(\\mathrm{NA}\\) 的 \\(\\sigma\\)，是把 Hopkins 的光瞳重叠归一到扫描机合同上；1953 年文本里没有这套符号，对照时不要倒灌。</p><p>厚掩模打破「物体是平面透过率」。1953 年的 \\(M(f)\\) 是薄屏。Erdmann 的严格近场是在物体频谱处替换 \\(M\\)，TCC 光学核可以留下。附录要防的误读是：Hopkins 过时所以 OPC 改 FDTD；过时的是薄屏，不是双线性成像。</p><p><span class="marginnote">不要给这篇论文发明 arXiv 编号。出处就是 Proc. Royal Society A, 1953。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本篇不插入主干课序，不替代 <a href="/litho/partial-coherence">partial-coherence</a> 的 \\(\\sigma\\) 定义课。不把 Hopkins 写成已经包含矢量成像与浸没。不讨论未公开的全芯片 TCC 压缩比。下一篇 Levinson 教材对照的是整本产线原理，不是再积一次 TCC。</p><p><span class="marginnote">计算光刻专文把逆问题放在这个前向之上。读 Hopkins 是为了知道逆的是哪一个算子，不是为了在 1953 年里找 ILT。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>附录对照 1953：像强度是物体频谱的双线性型，TCC 只含照明与瞳。</li><li>与主干 hopkins-tcc / 部分相干课对照，不重排课序。</li><li>薄屏假设会被 M3D 替换物体频谱，核的分离仍在。</li><li>不含胶、不含套刻。</li><li>出处：Hopkins, <em>Proc. R. Soc. A</em> 217, 408 (1953)；不发明预印本编号。</li></ul>',11))])}const f=n(d,[["render",C]]);export{T as __pageData,f as default};
